function decodePublic(v: Json<ShieldedTransactPublicValues>): ShieldedTransactPublicValues {
  return {
    tx: decodeTransaction(v.tx),
  };
}

function decodePath(v: Json<PathValue>): PathValue {
  return new PathValue({
    index: v.index,
    siblings: v.siblings.map((x) => new Field(x)),
  });
}

function decodeTransaction(v: Json<TransactionValue>): TransactionValue {
  return {
    root: new Field(v.root),
    asset: fromHex(v.asset),
    nullifiers: [new Field(v.nullifiers[0]), new Field(v.nullifiers[1])],
    commitments: [new Field(v.commitments[0]), new Field(v.commitments[1])],
    oldRoot: new Field(v.oldRoot),
    newRoot: new Field(v.newRoot),
    index: v.index,
    flow: decodeFlow(v.flow),
    memos: [fromHex(v.memos[0]), fromHex(v.memos[1])],
  };
}

function decodeFlow(v: Json<FlowValue>): FlowValue {
  return {
    vpubIn: BigInt(v.vpubIn),
    vpubOut: BigInt(v.vpubOut),
    fee: BigInt(v.fee),
    recipient: fromHex(v.recipient),
    relayer: fromHex(v.relayer),
  };
}
